CallbackReturn MyHardwareInterface::on_init(
  const hardware_interface::HardwareComponentInterfaceParams & params)
{
  if (
    hardware_interface::SystemInterface::on_init(params) != CallbackReturn::SUCCESS)
  {
    return CallbackReturn::ERROR;
  }

  const auto num_joints = info_.joints.size();
  if (num_joints != 2)
  {
    RCLCPP_FATAL(logger(), "MyHardwareInterface expects exactly 2 joints, got %zu", num_joints);
    return CallbackReturn::ERROR;
  }

  hw_positions_.resize(num_joints, 0.0);
  hw_velocities_.resize(num_joints, 0.0);
  hw_commands_.resize(num_joints, 0.0);

  for (size_t i = 0; i < num_joints; ++i)
  {
    const auto & joint = info_.joints[i];

    if (joint.command_interfaces.size() != 1 ||
        joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        logger(), "Joint '%s' must have exactly one 'position' command interface",
        joint.name.c_str());
      return CallbackReturn::ERROR;
    }

    if (joint.state_interfaces.size() != 2)
    {
      RCLCPP_FATAL(
        logger(), "Joint '%s' must have exactly 2 state interfaces (position, velocity)",
        joint.name.c_str());
      return CallbackReturn::ERROR;
    }

    double initial_position = 0.0;
    for (const auto & state_if : joint.state_interfaces)
    {
      if (state_if.name == hardware_interface::HW_IF_POSITION && !state_if.initial_value.empty())
      {
        initial_position = hardware_interface::stod(state_if.initial_value);
      }
    }
    hw_positions_[i] = initial_position;
    hw_commands_[i] = initial_position;
  }

  return CallbackReturn::SUCCESS;
}

CallbackReturn MyHardwareInterface::on_activate(const rclcpp_lifecycle::State & /*previous_state*/)
{
  for (size_t i = 0; i < info_.joints.size(); ++i)
  {
    // Avoid a jump on activation: start the command at the current position.
    hw_commands_[i] = hw_positions_[i];
    hw_velocities_[i] = 0.0;

    set_state(info_.joints[i].name + "/" + hardware_interface::HW_IF_POSITION, hw_positions_[i]);
    set_state(info_.joints[i].name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocities_[i]);
  }

  RCLCPP_INFO(logger(), "MyHardwareInterface activated");
  return CallbackReturn::SUCCESS;
}

CallbackReturn MyHardwareInterface::on_deactivate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  RCLCPP_INFO(logger(), "MyHardwareInterface deactivated");
  return CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHardwareInterface::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double dt = period.seconds();

  for (size_t i = 0; i < info_.joints.size(); ++i)
  {
    const double previous_position = hw_positions_[i];
    // Integrate the last received command into the reported state so that a
    // commanded position is reflected back through the state interfaces.
    hw_positions_[i] = hw_commands_[i];
    hw_velocities_[i] = dt > 0.0 ? (hw_positions_[i] - previous_position) / dt : 0.0;

    set_state(info_.joints[i].name + "/" + hardware_interface::HW_IF_POSITION, hw_positions_[i]);
    set_state(info_.joints[i].name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocities_[i]);
  }

  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHardwareInterface::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  for (size_t i = 0; i < info_.joints.size(); ++i)
  {
    hw_commands_[i] =
      get_command<double>(info_.joints[i].name + "/" + hardware_interface::HW_IF_POSITION);
  }

  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

